VOWELS = "aeiou"


def translate(text):
    return " ".join(_translate_word(word) for word in text.split())


def _translate_word(word):
    # Rule 1: word begins with a vowel, or starts with "xr" or "yt"
    if word[0] in VOWELS or word.startswith(("xr", "yt")):
        return word + "ay"

    # Rules 2-4: move the leading consonant cluster to the end.
    # "qu" always moves together with the consonants before it,
    # and "y" counts as a vowel once it is not the first letter.
    i = 0
    while i < len(word):
        c = word[i]
        if c in VOWELS or (c == "y" and i > 0):
            break
        if c == "q" and word[i + 1] == "u":
            i += 1
            break
        i += 1

    return word[i:] + word[:i] + "ay"

